const snippet=(lines,label)=>'<div class="ds-code-card ag-code"><div class="ds-code-bar"><span>'+escape(label||'Python · copy-ready')+'</span><button type="button" data-ds-copy aria-label="Copy Python code">Copy</button></div><pre><code>'+escape(lines.join('\n'))+'</code></pre></div>';
const heading=(id,num,title,desc)=>'<div class="ag-section-head"><span class="ag-kicker">'+num+'</span><h3 id="'+id+'">'+title+'</h3><p>'+desc+'</p></div>';
