 o.push('<section class="ag-section" aria-labelledby="ag-operations">'+heading('ag-operations','01 · REFERENCE','Common Python list operations and costs','Time and space costs for CPython lists. n = list length, m = inserted/appended count, k = slice length, u = distinct values. Unit-cost numeric operations/comparisons unless noted; custom equality, hashing, finalizers and big integers can add cost. Space separates algorithm state from allocator-dependent backing-array resize peaks; this is not NumPy complexity.'));
 const groups=[...new Set(d.operations.map(x=>x[0]))];
