 o.push(d.fundamentals.map((f,i)=>'<details class="ag-detail"'+(i===0?' open':'')+'><summary><span class="ag-number">'+String(i+1).padStart(2,'0')+'</span><strong>'+escape(f[0])+'</strong><span class="ag-chevron">⌄</span></summary><div class="ag-detail-body"><p>'+escape(f[1])+'</p>'+snippet(f[2],'Python example')+'<div class="ag-facts"><span><b>Time</b> '+big(f[3])+'</span><span><b>Space</b> '+big(f[4])+'</span></div><p class="ag-warning"><b>Common trap:</b> '+escape(f[5])+'</p></div></details>').join(''));
 o.push('</section>');
